    fn name(&self) -> &'static str {
        "tmpfs"
    }

    fn sync(&self) -> Result<()> {
        // do nothing
        Ok(())
    }

    fn root_inode(&self) -> Arc<dyn Inode> {
        self.inner.root_inode()
    }

    fn sb(&self) -> SuperBlock {
        // TODO: Tmpfs currently wraps RamFs, whose inodes still point to the
        // inner RamFs. Override statfs-visible fields here as a workaround
        // rather than changing the semantics of ordinary RamFs instances.
        let mut sb = self.inner.sb();
        let max_blocks = default_max_blocks();
        let max_inodes = default_max_inodes();

        sb.magic = TMPFS_MAGIC;
        sb.blocks = max_blocks;
        sb.bfree = max_blocks;
        sb.bavail = max_blocks;
        sb.files = max_inodes;
        sb.ffree = max_inodes;
        sb
    }

    fn fs_event_subscriber_stats(&self) -> &FsEventSubscriberStats {
        self.inner.fs_event_subscriber_stats()
    }
}

